document.querySelectorAll('.pw[role=listbox]').forEach(wheel => {
  const values = Array.from({ length: 12 }, (_, i) => String(i + 1));
  let index = values.indexOf(wheel.querySelector('[aria-selected=true]').textContent.trim());
  const draw = () => {
    wheel.innerHTML = '';
    for (let k = -2; k <= 2; k++) {
      const item = document.createElement('div');
      item.className = 'pw__i' + (k === 0 ? ' pw__s' : ''); item.setAttribute('role', 'option');
      item.setAttribute('aria-selected', String(k === 0)); item.textContent = values[(index + k + 12) % 12];
      if (k === 0) { item.id = 'pw-sel'; wheel.setAttribute('aria-activedescendant', 'pw-sel'); }
      item.addEventListener('click', () => { index = (index + k + 12) % 12; draw(); });
      wheel.appendChild(item);
    }
  };
  const move = n => { index = (index + n + 12) % 12; draw(); };
  wheel.addEventListener('keydown', e => {
    if (e.key === 'ArrowDown') { e.preventDefault(); move(1); } else if (e.key === 'ArrowUp') { e.preventDefault(); move(-1); }
    else if (e.key === 'Home') { e.preventDefault(); move(-index); } else if (e.key === 'End') { e.preventDefault(); move(11 - index); }
  });
  let acc = 0;
  wheel.addEventListener('wheel', e => { e.preventDefault(); acc += e.deltaY; if (Math.abs(acc) > 40) { move(acc > 0 ? 1 : -1); acc = 0; } }, { passive: false });
  draw();
});
